.track[data-settle] { stroke-dasharray: 4 6; }
.lit, .litDone { fill: none; stroke-width: 3; stroke-linecap: round; stroke-linejoin: round; }
.lit { stroke: var(--accent); }
.litDone { stroke: var(--success); }
