.balance { font-family: var(--font-display); font-size: var(--text-lg); font-variant-numeric: tabular-nums; }
.detail { position: absolute; top: calc(100% + 2px); left: 50%; width: 11rem; padding: var(--space-2) var(--space-3); transform: translateX(-50%); border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface-raised); box-shadow: var(--shadow-floating); color: var(--text-secondary); font-size: var(--text-xs); line-height: 1.35; opacity: 0; pointer-events: none; transition: opacity var(--duration-fast, .16s); z-index: 3; }
@media (hover: hover) { .stop:hover .detail { opacity: 1; } .stop:hover { z-index: 4; } }
.commissionLabel { position: absolute; transform: translate(-50%, 10px); color: var(--text-muted); font-size: var(--text-xs); }
.chip { position: absolute; transform: translate(-50%, -50%); padding: 3px var(--space-3); border-radius: var(--radius-pill); background: var(--accent); color: var(--accent-foreground); font-size: var(--text-xs); font-variant-numeric: tabular-nums; white-space: nowrap; box-shadow: var(--shadow-raised); z-index: 2; pointer-events: none; }
.chip[data-mode="approved"], .chip[data-mode="net"] { background: var(--success); color: var(--background); }
.steps { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--space-4); max-width: 760px; width: 100%; margin-inline: auto; font-size: var(--text-xs); color: var(--text-secondary); }
.steps > div { display: grid; gap: var(--space-1); }
